userscript.function:

$share.contObj = new SepoaContractObject(getEditorOptions());
$share.contObj.draw();
$share.contObj.attachEvent('onHeaderButtonClick', function(id){
    if(id == "SIGN"){
        doSign();
    } else if(id == "SIGN_REJECT") {
        doSignReject();
    } else if(id == "REVIEW_ACCEPT") {
        doReviewAccept();
    } else if(id == "REVIEW_REJECT") {
        doReviewReject();
    }
})


var imageServlet = sUtils.url.toQueryString({
    module:$share.config.editor.options.SERVICE,
    action:'doImage',
    CONT_NO:$share.config.document.CONT_NO,
    CONT_GL_SEQ:$share.config.document.CONT_GL_SEQ,
    FILE_ID:'$.{FILE_ID}',
    PART_ID:'$.{PART_ID}',
    ran:'$CURRENT{TIME_STRING}',
    's-token':'$CONFIG{TOKEN}'
}, false);
$share.contObj.setImageServlet(window.CONTEXT_NAME+'/SepoaActionController.sux?'+imageServlet)

var config = {
    url:window.CONTEXT_NAME+'/SepoaActionController.sux',
    on:{
        callback:function(res, config, params){
            if(res.status == "1" && res.result){
                $share.contObj.load(res.result[0], "json");
                doDataMapping();
            }else{
                Alert(res.message);
            }
        }
    }
}

var params = {
    module:$share.config.editor.options.SERVICE,
    action: "doImageList",
    CONNECTION: "CONNECTION",
    CONT_NO: $share.config.document.CONT_NO,
    CONT_GL_SEQ: $share.config.document.CONT_GL_SEQ
}
sUtils.multipart.send(config, params);


var data = {};
if($share.config.document.DOC_INFO_DATA){
    data.data = $.extend(true, {}, $share.config.document.DOC_ITEM, $share.config.document.DOC_INFO_DATA);
}
if($share.config.document.SIGNER){
    data.signer = $share.config.document.SIGNER;
}else if($share.config.module.WORK_TYPE == 'T'){
    data.signer = [];
    var signerArray = $share.config.document.DOC_INFO_DATA.SIGNER_CODE.split(',');
    for(var i in signerArray){
        if(signerArray[i]){
            data.signer.push({SIGNER_NO:signerArray[i]});
        }
    }
}

$share.contObj.setData(data);


$share.config.document.EDITOR_HTMLS = $share.contObj.getHtml();

if($share.config.editor.header){
    for(var i in $share.config.editor.header){
        var headerItem = $share.config.editor.header[i];
        switch(headerItem.type){
        case "form":
            if(!headerItem.obj.validate()){
                Alert(sUtils.cache.text.get('POA_CONTRACT.MESSAGE_0003'));
                return false;
            }
            $share.config.document.DOC_INFO_DATA = $.extend(true, {}, $share.config.document.DOC_INFO_DATA, headerItem.obj.getFormData(true));
            break;
        }
    }
}

if($share.config.module.WORK_TYPE == "T"){
    if(!$share.config.document.DOC_INFO_DATA){
        $share.config.document.DOC_INFO_DATA={}
    }
    $share.config.document.DOC_INFO_DATA.SIGNER_CODE = $share.contObj.getSignNumber()
}

return true;


$share.config.editor.options = {
    T:{
        SERVICE:'contract.template',
        SIGNER:{
            CONTORL:true,
            DEFAULT_COUNT:2
        }
    }, 
    C:{
        SERVICE:'contract',
        SIGNER:{
            CONTROL:false,
            DEFAULT_COUNT:0,
            REG_COMPANY_FLAG:'N'
        }
    }
}[$share.config.module.WORK_TYPE];

var moduleItems = {
    editor:{
        layout:"b",
        config:{
            mapping:{                             //if the key value of the data is different, change
                ID:'$.{FILE_ID}__$.{PART_ID}',    //default : ID
                IMAGE:"ID"                        //default : ID ; enter to use a different key
            },
            dynamic:true                          //default : true
        }
    }
}

var useContItem = false;
if($share.config.module.CONT_MODULE == "EDITOR"){
    if($share.config.module.WORK_TYPE == "T"){
        useContItem = true;    
    }   
}

if(useContItem){
    moduleItems=$.extend(true, moduleItems, {
        items:{
            layout:"a",
            item:{
                service:{
                    PROCESS_ID:"sepoa.svc.contract.SepoaContractItem",
                    METHOD:"doQuery",
                    PARAMS:{
                        CONT_TYPE:$share.config.module.CONT_TYPE,
                        CATEGORY:'COMMON'
                    }
                }
            },
            sign:{
                service:{
                    PROCESS_ID:"sepoa.svc.contract.SepoaContractItem",
                    METHOD:"doQuery",
                    PARAMS:{
                        CONT_TYPE:$share.config.module.CONT_TYPE,
                        CATEGORY:'SIGNER'
                    }
                },
                default:$share.config.editor.options.SIGNER.DEFAULT_COUNT,                  //init item count
                control:$share.config.editor.options.SIGNER.CONTROL,                        //default : true
                controlType:$share.config.editor.options.SIGNER.CONTROL_TYPE || 'default',  //default : 'default' [default, popup, custom]
                addFlag:$share.config.editor.options.SIGNER.ADD_FLAG,                       //default : true
                max:3,                                                                      //default : 9
                min:2,                                                                      //default : 1
                partnerAddFlag: $share.config.editor.options.SIGNER.REG_COMPANY_FLAG,       //default : false
                formOption: undefined,                                                      //default : undefined
            },
        },
        preview:[{
            layout:"c",
            config:{
                mapping:{       //if the key value of the data is different, change
                    ID:'$.{FILE_ID}__$.{PART_ID}',    //default : ID
                    IMAGE:"ID"  //default : ID ; enter to use a different key
                },
                title:sUtils.cache.text.get("POA_CONTRACT.LABEL_FILE_TYPE_C"),
                dynamic:true    //default : true
            }
       }]
    })
}else{
    moduleItems=$.extend(true, moduleItems, {
        preview:[
            {
                layout:"a",
                config:{
                    mapping:{                             //if the key value of the data is different, change
                        ID:'$.{FILE_ID}__$.{PART_ID}',    //default : ID
                        IMAGE:"ID"                        //default : ID ; enter to use a different key
                    },
                    title:sUtils.cache.text.get("POA_CONTRACT.LABEL_FILE_TYPE_C"),
                    type:['G','C','CZ'],                             //'C'ontract OR 'E'stimate
                    dynamic:true                          //default : true
                }
            },{
                layout:"c",
                config:{
                    mapping:{
                        ID:'$.{FILE_ID}__$.{PART_ID}',
                        IMAGE:"ID"
                    },
                    title:sUtils.cache.text.get("POA_CONTRACT.LABEL_FILE_TYPE_E"),
                    type:['E','EZ'],
                    dynamic:true
                }
            }
        ]
    });
}

return {
    layout:layoutObj,
    workType:$share.config.module.WORK_TYPE,
    module:moduleItems,
    header:$share.config.editor.header
}


Confirm(sUtils.cache.text.get('POA_CONTRACT.MESSAGE_0004'), function(result) {
    if(result){
        doUpdateShare();

        //check validate
        var doSelectedSignType=function(signType){
            doSignStart(signType);
        }

        if(SERVER_CERT_FLAG && sUtils.string.toBoolean(Sepoa.info.SERVER_SIGN_FLAG)){
            doSignEnd({
                SIGN_TYPE:'SERVER'
            });
        }else{
            var signType = $share.config.document.DOC_INFO_DATA.CONT_METHOD;
            if(!signType){
                signType = "D,C,P"
            }
            signType = signType.split(',');
            if(signType.length > 1){
                Confirm(sUtils.cache.text.get('POA_CONTRACT.MESSAGE_0020'), function(){
                    signType = 'C';
                    doSelectedSignType(signType);
                })
            }else{
                doSelectedSignType(signType);
            }
        }
    }
});


var config = {
    url:window.CONTEXT_NAME+'/SepoaActionController.sux',
    on:{
        callback:function(res, config, params){
            if(res.status == 1){
                Alert(sUtils.cache.text.get('POA_CONTRACT.MESSAGE_0001'), function(){
                    callFunction('p', 'doClose', [true]);
                })
            }else{
                Alert(res.message);
            }
        }
    }
}
var params = $.extend(true, {
    module:$share.config.editor.options.SERVICE,
    action: "doSign",
    CONT_NO: $share.config.document.CONT_NO,
    CONT_GL_SEQ: $share.config.document.CONT_GL_SEQ,
    SIGN_COMMENT: $share.config.document.DOC_INFO_DATA.SIGN_COMMENT,
    SIGN_FIX_HTML: JSON.stringify($share.contObj.getHtml(true))
}, data);
sUtils.multipart.send(config, params);


var doSelectClientSignInfo = function(signType){
    var config = {
        url:window.CONTEXT_NAME+'/SepoaActionController.sux',
        on:{
            callback:function(res, config, params){
                if(res.status == 1){
                    $share.toolkit[config._SIGN_TYPE.toLowerCase()].doSign({
                        SIGN_ORG_VALUE:res.result[0].SIGN_HASH,
                        SIGN_KEY:res.result[0].SIGN_KEY
                    });
                }
            }
        },
        _SIGN_TYPE:'NX'
    }

    var params = {
        module:$share.config.editor.options.SERVICE,
        action: "doSelectClientSignInfo",
        CONNECTION: "CONNECTION",
        CONT_NO: $share.config.document.CONT_NO,
        CONT_GL_SEQ: $share.config.document.CONT_GL_SEQ
    }
    sUtils.multipart.send(config, params);
}
if(signType == "C"){
    if(!$share.toolkit){
        $share.toolkit = {};
    }
    if(!$share.toolkit.nx){
        $share.toolkit.nx = new SepoaCertSign({
            module:"certModuleNX"
        });
        $share.toolkit.nx.attachEvent("onModuleReady", function(){
            doSelectClientSignInfo('NX');
        })
        $share.toolkit.nx.attachEvent("onSignPass", function(data){
            doSignEnd($.extend(true, {SIGN_TYPE:'NX'}, data));
        })
        $share.toolkit.nx.init();
    }else{
        doSelectClientSignInfo('NX');
    }
} else if(signType == "D") {
    if($share.contObj.checkSignField($share.config.editor.signerNo)) {
        doSignEnd({
            SIGN_TYPE:'D'
        });
    } else {
        Alert(sUtils.cache.text.get('POA_CONTRACT.MESSAGE_0032'));
    }
}


Confirm(sUtils.cache.text.get('POA_CONTRACT.MESSAGE_0024'), function(result) {
    if(result) {
        var config = {
            url:window.CONTEXT_NAME+'/SepoaActionController.sux',
            on:{
                callback:function(res, config, params){
                    if(res.status != 1){
                        Alert(res.message);
                    } else {
                        Alert(sUtils.cache.text.get('MESSAGE.0001'), function() {
                            callFunction('p', 'doClose', [true]);
                        });
                    }
                }
            }
        }

        var params = {
            module: $share.config.editor.options.SERVICE,
            action: "doSignReject",
            CONT_NO: $share.config.document.CONT_NO,
            CONT_GL_SEQ: $share.config.document.CONT_GL_SEQ
        }

        sUtils.multipart.send(config, params);
    }
});


Confirm(sUtils.cache.text.get('POA_CONTRACT.MESSAGE_0040'), function(result) {
    if(result) {
        doUpdateShare();
        var config = {
            url:window.CONTEXT_NAME+'/SepoaActionController.sux',
            on:{
                callback:function(res, config, params){
                    if(res.status != 1){
                        Alert(res.message);
                    } else {
                        Alert(sUtils.cache.text.get('MESSAGE.0001'), function() {
                            callFunction('p', 'doClose', [true]);
                        });
                    }
                }
            }
        }

        var params = {
            module : $share.config.editor.options.SERVICE,
            action : 'doReviewAccept',
            CONT_NO : $share.config.document.CONT_NO,
            CONT_GL_SEQ : $share.config.document.CONT_GL_SEQ,
            REVIEW_COMMENT : $share.config.document.DOC_INFO_DATA.REVIEW_REQ_COMMENT 
        }

        sUtils.multipart.send(config, params);
    }
});



Confirm(sUtils.cache.text.get('POA_CONTRACT.MESSAGE_0041'), function(result) {
    if(result) {
        doUpdateShare();
        var config = {
            url:window.CONTEXT_NAME+'/SepoaActionController.sux',
            on:{
                callback:function(res, config, params){
                    if(res.status != 1){
                        Alert(res.message);
                    } else {
                        Alert(sUtils.cache.text.get('MESSAGE.0001'), function() {
                            callFunction('p', 'doClose', [true]);
                        });
                    }
                }
            }
        }

        var params = {
            module: $share.config.editor.options.SERVICE,
            action: 'doReviewReject',
            CONT_NO: $share.config.document.CONT_NO,
            CONT_GL_SEQ: $share.config.document.CONT_GL_SEQ, 
            REVIEW_COMMENT: $share.config.document.DOC_INFO_DATA.REVIEW_REQ_COMMENT 
        }

        sUtils.multipart.send(config, params);
    }
});
